          if (!PCT.test(pct.trim())) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            save.reset();
            setInvalid(true);
            return;
          }
          setInvalid(false);
          save.mutate({ grade, pct: pct.trim(), from: from.trim() });
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
